#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_instance_norm_clamp_multiply_kernel(
    const float* input, const float* multiplier,
    float* output, int N, int C, int D, int H, int W,
    float clamp_min, float clamp_max, float eps) {

    int n = blockIdx.x;
    int c = blockIdx.y;
    int num_elements = D * H * W;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int idx = threadIdx.x; idx < num_elements; idx += blockDim.x) {
        int d = idx / (H * W);
        int hw = idx % (H * W);
        int h = hw / W;
        int w = hw % W;
        int input_idx = ((n * C + c) * D + d) * H * W + h * W + w;
        float val = input[input_idx];
        sum += val;
        sum_sq += val * val;
    }

    __shared__ float s_sum[256];
    __shared__ float s_sum_sq[256];
    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mean = s_sum[0] / num_elements;
        float variance = (s_sum_sq[0] / num_elements) - (mean * mean);
        float inv_std = rsqrtf(variance + eps);
        s_sum[0] = mean;
        s_sum_sq[0] = inv_std;
    }
    __syncthreads();

    float mean = s_sum[0];
    float inv_std = s_sum_sq[0];
    float mult = multiplier[c];

    for (int idx = threadIdx.x; idx < num_elements; idx += blockDim.x) {
        int d = idx / (H * W);
        int hw = idx % (H * W);
        int h = hw / W;
        int w = hw % W;
        int input_idx = ((n * C + c) * D + d) * H * W + h * W + w;
        float val = input[input_idx];
        float normalized = (val - mean) * inv_std;
        float clamped = fminf(fmaxf(normalized, clamp_min), clamp_max);
        output[input_idx] = clamped * mult;
    }
}

torch::Tensor fused_instance_norm_clamp_multiply_cuda(
    torch::Tensor input,
    torch::Tensor multiplier,
    float clamp_min,
    float clamp_max,
    float eps) {

    auto N = input.size(0);
    auto C = multiplier.size(0);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);
    auto output = torch::zeros_like(input);

    dim3 grid(N, C);
    int block_size = 256;
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    fused_instance_norm_clamp_multiply_kernel<<<grid, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        clamp_min, clamp_max, eps);

    return output;
}

__global__ void max_reduce_kernel(
    const float* input,
    float* output,
    int C,
    int D,
    int H,
    int W) {

    int n = blockIdx.x / (D * H * W);
    int residual = blockIdx.x % (D * H * W);
    int d = residual / (H * W);
    residual = residual % (H * W);
    int h = residual / W;
    int w = residual % W;

    int input_idx = n * C * D * H * W + d * H * W * C + h * W * C + w * C;
    float max_val = -INFINITY;

    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        float val = input[input_idx + c];
        max_val = fmaxf(max_val, val);
    }

    __shared__ float shared_max[256];
    int tid = threadIdx.x;
    shared_max[tid] = max_val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + stride]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        output[blockIdx.x] = shared_max[0];
    }
}

torch::Tensor max_reduce_cuda(torch::Tensor input) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);
    auto output = torch::zeros({N, 1, D, H, W}, input.options());

    int grid_size = N * D * H * W;
    int block_size = 256;

    max_reduce_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        C, D, H, W);

    return output;
}
